package com.aliothmoon.maafw.once;
import org.junit.Test;import java.nio.file.*;import static org.junit.Assert.*;
public class UiFieldProtocolTest {
 static final String N="0123456789abcdef0123456789abcdef";
 private NativeUiFieldDiagnostics.Result fields(){var a=new NativeUiFieldDiagnostics.Accumulator();a.node(0,-1,0,0,0,100,100,true,true,false,"android.webkit.WebView","","Search","0/30");return a.result();}
 private NativeUiStructureProtocol.Report report(){return new NativeUiStructureProtocol.Report(N,100,200,250,NativeUiStructureProtocol.Reason.OK,NativeUiStructureProtocol.Cleanup.CONFIRMED,1,10,1,0,0,0,100,100,-1,-1,NativeUiStructureProtocol.Task.unknown(),NativeUiStructureProtocol.Task.unknown(),new NativeUiReadyDiagnostics.Result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED,1,0,0,0,0,0,0,1),fields());}
 @Test public void exactFormatModeRoundTrip(){var r=report();String s=NativeUiStructureProtocol.encode(r);assertTrue(s.startsWith("UIS3|"));assertEquals(r,NativeUiStructureProtocol.parse(s,N,90,1000,300,true,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s,N,90,1000,300,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s,N,90,1000,300,false,true));}
 @Test public void fieldCannotCarryKnownCounter(){var r=report();assertThrows(IllegalArgumentException.class,()->new NativeUiStructureProtocol.Report(N,100,200,250,r.reason(),r.cleanup(),1,10,1,0,0,0,100,100,-1,-1,new NativeUiStructureProtocol.Task(NativeUiStructureProtocol.Status.KNOWN,0,30,1,NativeUiStructureProtocol.Unit.EXPLICIT_TEXT_POINTS),r.reading(),r.readiness(),r.fieldDiagnostics()));}
 @Test public void metadataOnlyAfterFinalGate(){var r=report();String summary=r.fieldDiagnostics().summary();assertTrue(new UiStructurePublication(r,true,1000).publish(300,true,true,true).contains(summary));for(String s:new String[]{new UiStructurePublication(r,true,1000).publish(300,false,true,true),new UiStructurePublication(r,true,1000).publish(300,true,false,true),new UiStructurePublication(r,true,1000).publish(300,true,true,false),new UiStructurePublication(r,false,1000).publish(300,true,true,true),new UiStructurePublication(r,true,20000).publish(15101,true,true,true)}){assertFalse(s.contains(summary));assertTrue(s.contains("publicationFence=REJECTED_AT_APPEND"));}}
 @Test public void exactBoundsAndOldVersionCannotBeReplayed(){String s=NativeUiStructureProtocol.encode(report());assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s+"|0",N,90,1000,300,true,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse("A".repeat(16385),N,90,1000,300,true,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s.replace("UIS3","UIS2"),N,90,1000,300,true,true));}
 @Test public void formatReaderCapCannotExpandLegacy(){byte[] s=("A".repeat(5000)+"\n").getBytes(java.nio.charset.StandardCharsets.US_ASCII);assertFalse(AndroidUiStructureReader.validFrame(s,s.length));assertTrue(AndroidUiStructureReader.validFrame(s,s.length,true));byte[] over=("A".repeat(16384)+"\n").getBytes(java.nio.charset.StandardCharsets.US_ASCII);assertFalse(AndroidUiStructureReader.validFrame(over,over.length,true));}
 @Test public void fixedCompiledModeChoosesFormatArg()throws Exception{String rel="app/src/main/java/com/aliothmoon/maafw/once/AndroidUiStructureReader.java";Path path=Path.of(System.getProperty("staging.root","."),rel);if(!Files.exists(path))path=Path.of("..",rel);String s=Files.readString(path);assertTrue(s.contains("ReadOnlyCheckpoint.CURRENT == ReadOnlyCheckpoint.UI_FIELD_V51"));assertTrue(s.contains("locatedMode ? \"DIAGNOSTIC_LOCATED_V52\" : \"DIAGNOSTIC_V51\";"));assertTrue(s.contains("readyMode || formatMode || fieldMode || boundMode, fieldMode, boundMode"));}
 @Test public void fieldRejectsMismatchedFullTreeCount(){var r=report();assertThrows(IllegalArgumentException.class,()->new NativeUiStructureProtocol.Report(N,100,200,250,r.reason(),r.cleanup(),2,10,1,0,0,0,100,100,-1,-1,r.search(),r.reading(),r.readiness(),r.fieldDiagnostics()));}
 @Test public void metadataRejectsAtDeadlineAndRepeatedAppend(){var r=report();String summary=r.fieldDiagnostics().summary();assertFalse(new UiStructurePublication(r,true,300).publish(300,true,true,true).contains(summary));var t=new UiStructurePublication(r,true,1000);assertTrue(t.publish(300,true,true,true).contains(summary));assertFalse(t.publish(301,true,true,true).contains(summary));}
}
